def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, id, qty)
    sell_book = []  # (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, arrival_time) for cancel validation
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, arr_time = order_map[cancel_id]
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != cancel_id]
                del order_map[cancel_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[4] if order_type != 'market' else order[3]
            price = order[3] if order_type != 'market' else None

            order_map[order_id] = (side, arrival_time)

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    sell_book.sort()  # (price, arrival_time, id, qty)
                    best_sell = sell_book[0]
                    sell_price, sell_time, sell_id, sell_qty = best_sell

                    # Check if match is possible
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        qty -= trade_qty

                        if trade_qty == sell_qty:
                            sell_book.pop(0)
                            del order_map[sell_id]
                        else:
                            sell_book[0] = (sell_price, sell_time, sell_id, sell_qty - trade_qty)
                    else:
                        break

                # Add remaining qty to buy_book if limit or ioc with qty > 0
                if qty > 0 and order_type in ['limit', 'ioc']:
                    if order_type == 'limit':
                        buy_book.append((price, arrival_time, order_id, qty))
                    else:  # ioc
                        del order_map[order_id]
                elif qty > 0 and order_type == 'market':
                    del order_map[order_id]
                elif qty == 0 and order_type in ['ioc', 'market']:
                    del order_map[order_id]

            else:  # side == 'sell'
                # Match against buy_book
                while qty > 0 and buy_book:
                    buy_book.sort(key=lambda x: (-x[0], x[1]))  # highest price first, then earliest
                    best_buy = buy_book[0]
                    buy_price, buy_time, buy_id, buy_qty = best_buy

                    # Check if match is possible
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        qty -= trade_qty

                        if trade_qty == buy_qty:
                            buy_book.pop(0)
                            del order_map[buy_id]
                        else:
                            buy_book[0] = (buy_price, buy_time, buy_id, buy_qty - trade_qty)
                    else:
                        break

                # Add remaining qty to sell_book if limit or ioc with qty > 0
                if qty > 0 and order_type in ['limit', 'ioc']:
                    if order_type == 'limit':
                        sell_book.append((price, arrival_time, order_id, qty))
                    else:  # ioc
                        del order_map[order_id]
                elif qty > 0 and order_type == 'market':
                    del order_map[order_id]
                elif qty == 0 and order_type in ['ioc', 'market']:
                    del order_map[order_id]

        arrival_time += 1

    return trades

